(* Modified by Theorem Labs, 2026-11: ported to LPS 727298f3 (the segment is checked at both CONFIG_RSEQ values from the hand-off state the previous segment computes, the plan's fresh variables renumbered by a map read from a probe run, and its own hand-off state computed in the build; the AT_RANDOM copy's split chain splits off its seven top values with the register values the run gives there, as zstd/fse_read_ncount's does; the hand-off states collected in one run of the check; the segment's shape written as the literal its check computes, read from a probe run). *)
From Stdlib Require Import ZArith List Bool Lia.
From OSSVerify.Proofs.msgpack_c.unpack_pack_fuzzer.lib.AS Require Import AxSymExec3 AsanPlanCore AsanPlan AsanPlanSound AsanPlanImages AsanInit AsanNodesWJoin AsanStartup StartupPlanAsan PlanRegen AsanStartupCert AsanStartupCertB.
Import ListNotations. Import AX2. Import AP.
Open Scope Z_scope.

Definition ITC : itab := mk_itab_ranges ASEGS startup_plan_ranges.
Lemma ITC_ok : itab_sound ASEGS ITC.
Proof. apply APS.mk_itab_ranges_sound. Qed.
From Ltac2 Require Import Ltac2 Constr Std Control.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac2 vm_cert_refl (rhs : constr) :=
  let g := Control.goal () in
  let r := constr:(@eq_refl cres $rhs) in
  Std.exact_no_check (Constr.Unsafe.make (Constr.Unsafe.Cast r Constr.Cast.vm g)).

(* read in a probe run (probe MP1, "MP1 MAPPT asan segB r0") *)
Definition vshC : list (nat * nat) := [(13, 17); (207, 211); (310, 316); (344, 350)]%nat.
(* this segment's fresh-variable floor: the counter of the state the previous segment hands off, computed
   (the recorded plan's was the old run's) *)
Definition NXC (r : Z) : nat := nxt (HB r).
Lemma NXC_ge : forall r, (NX0 <= NXC r)%nat.
(* the default state of [hstate] (the previous segment's start state, open in [r]) is generalized
   before the [vm_compute]: the table has the key, so the default is never read, and an open start
   state is not normalised *)
Proof. ltac1:(intros r; apply Nat.leb_le; unfold NXC, HB, HSL_B; destruct (Z.eqb r 1); generalize (HA r); intros d; vm_compute; reflexivity). Qed.
(* the check run itself, as an abbreviation and not a definition: the certificates below are then stated in
   the form the start-up's segment lemma ([AsanBoot.seg_sound]) takes as its premise, which the kernel meets
   argument by argument; through a definition, it unfolded [check] and reduced the whole plan check lazily *)
#[local] Notation runC_with r p js :=
  (check ASEGS ITC ASAN (NXC r) AsanInit.LIMIT r (XNS ASEGS ASAN (NXC r) AsanInit.LIMIT) XE0 XB0 js KC0 BFUEL FUEL None (HB r) p).
(* the same check run once by [check_coll] (AsanPlan.v), giving each hand-off it reaches to
   PlanRegen's [hvisit], from [bm] (the collector's fuel left and its hand-off map); the tables
   below are collected in that one run ([collect_handoffs1]) *)
Definition collC_with (r : Z) (p : plan) (bm : nat * list (nat * acs)) : cres * (nat * list (nat * acs)) :=
  check_coll ASEGS ITC ASAN (NXC r) AsanInit.LIMIT r (XNS ASEGS ASAN (NXC r) AsanInit.LIMIT) XE0 XB0 KC0 BFUEL _ hvisit FUEL None (HB r) p bm.

(* THE AT_RANDOM COPY'S SPLIT CHAIN.  The recorded plan splits [e_atr8] into one generic branch for the values up
   to the old range's top and one branch per value above it (391 and below, registers 13 and 14 respelled as the
   literals the old run gave).  [e_atr8]'s range in the computed hand-off state ends 4 r lower (the vector is 32 r
   bytes longer), and the generic branch cannot read the shadow word near that top.  The chain is made again by the
   same rule from the computed state, in the build: generic up to [top - 7], then one branch for each of the seven
   top values, each respelling registers 13 and 14 as the literals the run gives in that branch (read with the
   branch cut at [PHandoff (900 + k)]; both registers have one value there, [xlo = xhi]).  The rule is zstd/
   fse_read_ncount's (its probe P8); the certificate re-checks the result. *)
Definition atr8_top (cs : acs) : Z :=
  match find (fun K => match K with KRange x _ _ => expr_eqb x e_atr8 | _ => false end) (kn cs) with
  | Some (KRange _ _ hi) => hi | _ => 0 end.
Definition is_chain (p : plan) : bool :=
  match p with PSplit e m _ _ => (expr_eqb e e_atr8 && Z.eqb m 17592186044384)%bool | _ => false end.
Definition qc2_k : plan := psh (mapf vshC) startup_plan_qc2.
Fixpoint chain_from (i : Z) (ls : list plan) : plan :=
  match ls with [] => PContra | [l] => l | l :: rest => PSplit e_atr8 i l (chain_from (i + 1) rest) end.
Definition chain (t : Z) (ls : list plan) : plan := PSplit e_atr8 (t - 7) qc2_k (chain_from (t - 6) ls).
Definition swap_chain (q : plan) (p : plan) : option plan := if is_chain p then Some q else None.
Definition planC_with (t : Z) (ls : list plan) : plan := pmapH (swap_chain (chain t ls)) (psh (mapf vshC) startup_plan_segB).
Definition TopC0 : Z := Eval vm_compute in atr8_top (HB 0).
Definition TopC1 : Z := Eval vm_compute in atr8_top (HB 1).
Definition cuts : list plan := map (fun k => PHandoff (900 + k)%nat) (seq 0 7).
Definition CutT0 : list (nat * acs) := Eval vm_compute in collect_handoffs1 40 (collC_with 0 (planC_with TopC0 cuts)) [].
Definition CutT1 : list (nat * acs) := Eval vm_compute in collect_handoffs1 40 (collC_with 1 (planC_with TopC1 cuts)) [].
Definition rlit (t : list (nat * acs)) (k : nat) : option Z * option Z * option Z * option Z :=
  match hlookup t (900 + k)%nat with
  | Some cs => (xlo (kn cs) (reg cs 13), xhi (kn cs) (reg cs 13), xlo (kn cs) (reg cs 14), xhi (kn cs) (reg cs 14))
  | None => (None, None, None, None) end.
Definition LitsC0 := Eval vm_compute in map (rlit CutT0) (seq 0 7).
Definition LitsC1 := Eval vm_compute in map (rlit CutT1) (seq 0 7).
Definition leaf (q : option Z * option Z * option Z * option Z) : plan :=
  match q with
  | (Some a, Some b, Some c, Some d) => if (Z.eqb a b && Z.eqb c d)%bool then PRespell 13 (ELit a) (PRespell 14 (ELit c) qc2_k) else PContra
  | _ => PContra end.
Definition planC (r : Z) : plan := if Z.eqb r 1 then planC_with TopC1 (map leaf LitsC1) else planC_with TopC0 (map leaf LitsC0).
#[local] Notation runC r js := (runC_with r (planC r) js).
Definition HSL_C0 : list (nat * acs) := Eval vm_compute in collect_handoffs1 40 (collC_with 0 (planC 0)) [].
Definition HSL_C1 : list (nat * acs) := Eval vm_compute in collect_handoffs1 40 (collC_with 1 (planC 1)) [].
Definition HSL_C (r : Z) : list (nat * acs) := if Z.eqb r 1 then HSL_C1 else HSL_C0.
Definition HS_asanC (r : Z) (h : nat) : option acs := hlookup (HSL_C r) h.
Lemma HSL_C_keys : forall r, map fst (HSL_C r) = [12%nat].
Proof. ltac1:(intros r; unfold HSL_C; destruct (Z.eqb r 1); vm_compute; reflexivity). Qed.
Definition HC (r : Z) : acs := hstate (HSL_C r) (HB r) 12.
Lemma HS_asanC_one : forall r h ch, HS_asanC r h = Some ch -> h = 12%nat /\ ch = HC r.
Proof. ltac1:(intros r h ch H; exact (hlookup_one (HSL_C r) (HB r) 12 (HSL_C_keys r) h ch H)). Qed.
